  Reject $fresh DUPLICATE_EVENT (Insert-Sql A2 EV1 REQ2 ('e'*64));Reject $fresh DUPLICATE_EVIDENCE (Insert-Sql A3 EV3 REQ3 ('d'*64));Reject $fresh UPPERCASE_HASH (Insert-Sql A4 EV4 REQ4 ('D'*64));Reject $fresh INVALID_ENVIRONMENT (Insert-Sql A5 EV5 REQ5 ('5'*64) SUCCESS NULL 1 "REPEAT('b',64)" 1 DEV);Reject $fresh MISSING_SUCCESS_FACTS (Insert-Sql A6 EV6 REQ6 ('6'*64) SUCCESS NULL NULL NULL NULL);Reject $fresh INVALID_OUTCOME (Insert-Sql A7 EV7 REQ7 ('7'*64) UNKNOWN);Reject $fresh NEGATIVE_COUNT (Insert-Sql A8 EV8 REQ8 ('8'*64) SUCCESS NULL 1 "REPEAT('b',64)" -1)
  $rejected=Invoke-Sql $fresh (Insert-Sql AR1 EVR1 REQR1 ('9'*64) REJECTED "'INVALID_ROLE'" NULL NULL NULL);Set-Check REJECTED_INSERT ($rejected.Code-eq0) $rejected.Output;$failed=Invoke-Sql $fresh (Insert-Sql AF1 EVF1 REQF1 ('0'*64) FAILED "'DB_DEPENDENCY_FAILURE'" NULL NULL NULL);Set-Check FAILED_INSERT ($failed.Code-eq0) $failed.Output
  foreach($concurrency in 10,25,50){$jobs=@();for($i=1;$i-le$concurrency;$i++){$id="C$concurrency-$i";$hash=('{0:x64}' -f ($concurrency*1000+$i));$sql=Insert-Sql $id "E-$id" "R-$id" $hash;$jobs+=Start-Job -ScriptBlock {param($exe,$port,$statement)&$exe --protocol=TCP --host=127.0.0.1 --port=$port --user=root --database=enterprise_platform "--execute=$statement"} -ArgumentList $mysql,$fresh.Port,$sql};$jobs|Wait-Job|Out-Null;$jobErrors=@($jobs|Where-Object State -ne Completed).Count;$jobs|Receive-Job|Out-Null;$jobs|Remove-Job;$actual=[int](Invoke-Sql $fresh "SELECT COUNT(*) FROM approval_role_directory_provider_audit WHERE audit_id LIKE 'C$concurrency-%'" -Raw).Output.Trim();Set-Check "CONCURRENCY_$concurrency" ($actual-eq$concurrency-and$jobErrors-eq0) "rows=$actual jobs=$jobErrors"}
  $beforeRestart=(Invoke-Sql $fresh 'SELECT COUNT(*) FROM approval_role_directory_provider_audit' -Raw).Output.Trim();&$admin --protocol=TCP --host=127.0.0.1 --port=$($fresh.Port) --user=root shutdown|Out-Null;Wait-Process -Id $fresh.Process.Id -ErrorAction SilentlyContinue;$fresh.Process=Start-Process $mysqld -ArgumentList "--defaults-file=$($fresh.Ini)" -WindowStyle Hidden -PassThru;for($i=0;$i-lt100;$i++){&$admin --protocol=TCP --host=127.0.0.1 --port=$($fresh.Port) --user=root ping 2>$null|Out-Null;if(!$LASTEXITCODE){break};Start-Sleep -Milliseconds 300};$afterRestart=(Invoke-Sql $fresh 'SELECT COUNT(*) FROM approval_role_directory_provider_audit' -Raw).Output.Trim();Set-Check RESTART_RECOVERY ($beforeRestart-eq$afterRestart) "$beforeRestart/$afterRestart"
  $summary=[ordered]@{result=if($failures.Count){'FAIL'}else{'PASS'};output_root=$OutputRoot;mysql=(&$mysql --version);flyway=((&$flyway -v 2>&1)-join' ');sha256=$sha;flyway_checksum=$checksum;fresh_schema_fingerprint=$freshFp;upgrade_schema_fingerprint=$upgradeFp;checks=$checks;rows_after_restart=$afterRestart;failures=$failures};$summary|ConvertTo-Json -Depth 8|Tee-Object -FilePath (Join-Path $evidence summary.json);if($failures.Count){exit 2}
}finally{foreach($server in $servers){$old=$ErrorActionPreference;$ErrorActionPreference='Continue';&$admin --protocol=TCP --host=127.0.0.1 --port=$server.Port --user=root shutdown 2>$null|Out-Null;$ErrorActionPreference=$old;if($server.Process-and!$server.Process.HasExited){Stop-Process -Id $server.Process.Id -Force -ErrorAction SilentlyContinue}}}
